import (
	"strings"
	"unicode"
)

// For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
// >>> FlipCase('Hello')
// 'hELLO'
func FlipCase(str string) string {
	var sb strings.Builder
	for _, ch := range str {
		switch {
		case unicode.IsUpper(ch):
			sb.WriteRune(unicode.ToLower(ch))
		case unicode.IsLower(ch):
			sb.WriteRune(unicode.ToUpper(ch))
		default:
			sb.WriteRune(ch)
		}
	}
	return sb.String()
}
```

**How it works:**

1. Iterate over each rune (Unicode code point) in the input string.
2. Use `unicode.IsUpper` / `unicode.IsLower` to determine the case of the character.
3. Apply the corresponding conversion:
   - Uppercase → `unicode.ToLower`
   - Lowercase → `unicode.ToUpper`
   - Non-letter → pass through unchanged
4. Build the result with a `strings.Builder` for efficient string concatenation.

**Example:**

```go
fmt.Println(FlipCase("Hello"))    // "hELLO"
fmt.Println(FlipCase("Go1.18"))   // "gO1.18"
fmt.Println(FlipCase("ABCdef"))   // "abcDEF"
fmt.Println(FlipCase("12345!"))   // "12345!"
```

